import{_ as t,o as n,c as o,a1 as i}from"./chunks/framework.DdbKPUhY.js";const p=JSON.parse('{"title":"Connection API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/connection-api.md","filePath":"spec/connection-api.md"}'),r={name:"spec/connection-api.md"};function s(c,e,a,l,d,u){return n(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="connection-api-spec" tabindex="-1">Connection API Spec <a class="header-anchor" href="#connection-api-spec" aria-label="Permalink to &quot;Connection API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Connection module manages TCP connections, HTTP parsing via llhttp, request/response lifecycle, and connection cleanup. Each connection is tied to a single TCP socket and handles one or more HTTP requests (keep-alive).</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-connection-new" tabindex="-1">uvhttp_connection_new <a class="header-anchor" href="#uvhttp-connection-new" aria-label="Permalink to &quot;uvhttp_connection_new&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_connection_new(uvhttp_server_t* server, uvhttp_connection_t** conn)</code></li><li><strong>Purpose</strong>: Create a new connection object for an accepted TCP socket</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. <code>conn</code> must be non-NULL.</li><li><strong>Postconditions</strong>: On success, <code>*conn</code> points to a valid connection with <code>state=UVHTTP_CONN_STATE_NEW</code>, <code>server</code> set, <code>tcp_handle</code> initialized.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: server or conn is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li><li><code>UVHTTP_ERROR_CONNECTION_LIMIT</code>: server is at max connections</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-connection-start" tabindex="-1">uvhttp_connection_start <a class="header-anchor" href="#uvhttp-connection-start" aria-label="Permalink to &quot;uvhttp_connection_start&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_connection_start(uvhttp_connection_t* conn)</code></li><li><strong>Purpose</strong>: Start reading from the connection</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid, in NEW state.</li><li><strong>Postconditions</strong>: State transitions to <code>UVHTTP_CONN_STATE_HTTP_READING</code>. Read callback is registered.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: conn is NULL</li><li><code>UVHTTP_ERROR_CONNECTION_INIT</code>: failed to start reading</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-connection-close" tabindex="-1">uvhttp_connection_close <a class="header-anchor" href="#uvhttp-connection-close" aria-label="Permalink to &quot;uvhttp_connection_close&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_connection_close(uvhttp_connection_t* conn)</code></li><li><strong>Purpose</strong>: Initiate connection close. Resources are freed in the close callback.</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid. Can be NULL (no-op).</li><li><strong>Postconditions</strong>: TCP handle close is initiated. Resources are freed in <code>on_handle_close</code> callback.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-connection-free" tabindex="-1">uvhttp_connection_free <a class="header-anchor" href="#uvhttp-connection-free" aria-label="Permalink to &quot;uvhttp_connection_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_connection_free(uvhttp_connection_t* conn)</code></li><li><strong>Purpose</strong>: Free connection resources immediately</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid. Should only be called after close is complete.</li><li><strong>Postconditions</strong>: All connection memory is freed. The <code>freed</code> flag prevents double-free.</li><li><strong>Error conditions</strong>: NULL conn is a no-op.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-connection-set-state" tabindex="-1">uvhttp_connection_set_state <a class="header-anchor" href="#uvhttp-connection-set-state" aria-label="Permalink to &quot;uvhttp_connection_set_state&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_connection_set_state(uvhttp_connection_t* conn, uvhttp_connection_state_t state)</code></li><li><strong>Purpose</strong>: Update connection state</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid.</li><li><strong>Postconditions</strong>: <code>conn-&gt;state</code> is updated.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h2 id="connection-states" tabindex="-1">Connection States <a class="header-anchor" href="#connection-states" aria-label="Permalink to &quot;Connection States&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NEW → HTTP_READING → (request complete) → HTTP_WRITING → (response sent) → HTTP_READING</span></span>
<span class="line"><span>NEW → HTTP_READING → (error) → CLOSING → CLOSED</span></span>
<span class="line"><span>NEW → HTTP_READING → (upgrade) → WEBSOCKET_OPEN → WEBSOCKET_CLOSING → CLOSED</span></span></code></pre></div><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Keep-Alive</strong>: After a response is sent, the connection returns to HTTP_READING state for the next request. The keep-alive timeout is configurable.</p></li><li><p><strong>Request/response lifecycle</strong>: Each request creates a <code>uvhttp_request_t</code> and <code>uvhttp_response_t</code> pair. These are recycled for keep-alive connections.</p></li><li><p><strong>Error handling</strong>: Parse errors, timeout, or connection reset transition to CLOSING state. The error is logged and the connection is cleaned up.</p></li><li><p><strong>Double-free protection</strong>: The <code>freed</code> flag prevents double-free. All cleanup functions check this flag before proceeding.</p></li><li><p><strong>TLS support</strong>: When TLS is enabled, read/write operations go through mbedtls SSL functions instead of raw TCP.</p></li><li><p><strong>WebSocket upgrade</strong>: When a WebSocket upgrade request is detected, the connection transitions to WebSocket mode.</p></li></ol><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Connection creation and destruction</li><li>State transitions</li><li>Keep-Alive request/response cycle</li><li>Error handling (parse errors, timeout)</li><li>Double-free protection</li><li>TLS connection lifecycle</li><li>WebSocket upgrade path</li><li>NULL parameter handling for all public functions</li><li>Connection limit enforcement</li></ul>`,20)])])}const _=t(r,[["render",s]]);export{p as __pageData,_ as default};
